from __future__ import annotations

import base64
import html
import re
from pathlib import Path

import streamlit as st

BASE_DIR = Path(__file__).resolve().parent
ASSETS_DIR = BASE_DIR / "assets"
SITE_URL = "https://anobus.jp/"


def image_data_uri(filename: str) -> str:
    path = ASSETS_DIR / filename
    if not path.exists():
        raise FileNotFoundError(f"画像が見つかりません: {path}")
    suffix = path.suffix.lower()
    mime = "image/jpeg" if suffix in {".jpg", ".jpeg"} else "image/png"
    encoded = base64.b64encode(path.read_bytes()).decode("ascii")
    return f"data:{mime};base64,{encoded}"


def font_data_uri(filename: str) -> str:
    path = ASSETS_DIR / filename
    if not path.exists():
        raise FileNotFoundError(f"フォントが見つかりません: {path}")
    encoded = base64.b64encode(path.read_bytes()).decode("ascii")
    return f"data:font/ttf;base64,{encoded}"


def load_assets() -> dict[str, str]:
    files = {
        "logo": "logo.png",
        "bus": "bus.png",
        "piggy": "piggy-bank-v2.png",
        "seats": "seats-v2.png",
        "point_coin": "point-coin-v2.png",
        "pixel_font": "DotGothic16-Regular.ttf",
        "dog": "dog.png",
        "cat": "cat.png",
        "usagi": "usagi.png",
        "usagi2": "usagi2.png",
        "women": "women.png",
        "city": "city-background.png",
        "castle": "castle.png",
        "fuji": "fuji.png",
        "sattue": "sattue.png",
        "tokyo_tower": "tokyo-tower.png",
        "tower": "tower.png",
        "interior": "photo_bus_interior.JPG",
        "fv_ornaments_left": "fv-night-ornaments-left.png",
        "fv_ornaments_right": "fv-night-ornaments-right.png",
    }
    assets = {
        key: image_data_uri(filename)
        for key, filename in files.items()
        if key != "pixel_font"
    }
    assets["pixel_font"] = font_data_uri(files["pixel_font"])
    return assets


